const uiCrew = () => { const vs = G().visits.filter(v => v.crewId === 'CR-1').slice(2, 6); return phoneMini(`<b style="font-size:.9rem">Hoy · ${vs.length + 7} paradas</b>` + vs.map(v => `<div style="background:var(--surface);border:1px solid var(--border);border-radius:10px;padding:8px;display:grid;gap:2px"><div class="flex between"><b>${v.stop}. ${esc(v.client.split(' ')[0])}</b>${h.pill({ Done: 'Hecho', 'In progress': 'En curso', 'En route': 'En camino' }[v.status] || 'Programado', v.status === 'Done' ? 'ok' : v.status === 'In progress' ? 'info' : '')}</div><span class="t3">${esc(v.start)} · ${esc(v.address)}</span></div>`).join('') + `<div style="background:var(--primary);color:var(--on-primary);border-radius:10px;padding:10px;text-align:center;font-weight:750">${icon('camera')} Fotos y terminar</div>`); };
const uiPortal = () => { const D = G(); return `<div style="display:grid;gap:8px">${h.card({ title: 'Hi ' + esc(D.res.primary.split(' ')[0]), sub: esc(D.res.property), body: h.list([{ icon: 'calendar', tone: 'info', title: 'Next visit Tuesday', sub: 'Weekly mowing · crew arrives 8-10 am' }, { icon: 'pen', tone: 'ok', title: 'Proposal ' + esc(D.proposals[0].id) + ' signed', sub: esc(D.res.project) }, { icon: 'card', title: 'Autopay on', sub: 'Bank account ending 6789' }]) })}</div>`; };
const uiPayments = () => h.table([{ k: 'what', label: 'Payment' }, { k: 'm', label: 'Method' }, { k: 'a', label: 'Amount', n: true, fmt: v => money(v, { cents: true }) }, { k: 's', label: 'Stripe fee', n: true, fmt: v => money(v, { cents: true }) }, { k: 'r', label: 'Rootline fee', n: true, fmt: v => `<b style="color:var(--ok-text)">${money(v, { cents: true })}</b>` }], [{ what: 'Deposit on PR-2290', m: 'ACH', a: 9420, s: 5, r: 0 }, { what: 'Season prepay', m: 'ACH', a: 4800, s: 5, r: 0 }, { what: 'Weekly mowing', m: 'Card on file', a: 185, s: 5.67, r: 0 }], { dense: true });
