const uiBooks = () => h.table([{ k: 'acct', label: 'Account' }, { k: 'dr', label: 'Debit', n: true, fmt: v => v ? money(v, { cents: true }) : '' }, { k: 'cr', label: 'Credit', n: true, fmt: v => v ? money(v, { cents: true }) : '' }], [{ acct: '1000 Operating checking', dr: 4812.4 }, { acct: '6300 Processing fees', dr: 141.6 }, { acct: '1050 Stripe clearing', cr: 4954 }], { dense: true, foot: ['JE-10446 · Stripe payout, balanced', '$4,954.00', '$4,954.00'] });
const uiMarketing = () => h.table([{ k: 'name', label: 'Campaign' }, { k: 'status', label: 'Status' }, { k: 'sent', label: 'Sent', n: true, fmt: v => num(v) }, { k: 'conv', label: 'Booked', n: true, fmt: v => v == null ? '-' : v }], G().campaigns, { dense: true });
