  const shown = all.filter(p => filt === 'all' || p.rating.startsWith(filt) || (filt === 'Not' && /^(Not|Invasive)/.test(p.rating)));
  const pals = PALETTES(c), pal = pals.find(p => p.id === U('pub.pal', 'pollinator')) || pals[0];
