// www.resources (21 §5.6; one or more working calculators)
// =====================================================================
RL.screen('www.resources', (c) => {
  const tool = U('pub.calc', 'mulch');
  const f = (k, d) => N('rc.' + k, d);
  const inp = (k, d, label, unit) => `<label class="fld"><span>${label}</span><span class="flex nw" style="gap:6px">${h.input(f(k, d), { ui: 'rc.' + k, type: 'number', label })}<span class="tiny t3 nowrap">${unit}</span></span></label>`;
  const out = (label, value, sub) => `<div class="kp"><span class="l">${label}</span><span class="v">${value}</span>${sub ? `<span class="d">${sub}</span>` : ''}</div>`;
  let calc;
  if (tool === 'paver') {
    const L = f('pl', 16), W = f('pw', 20), waste = f('pwaste', 10), base = f('pbase', 6), area = L * W;
    const baseYd = area * base / 12 / 27 * 1.15, sandYd = area * 1 / 12 / 27;
    calc = `${grid(140, [inp('pl', 16, 'Length', 'ft'), inp('pw', 20, 'Width', 'ft'), inp('pwaste', 10, 'Cut waste', '%'), inp('pbase', 6, 'Gravel base', 'in')], { gap: 10 })}
      <div class="kpis">${out('Pavers to order', num(Math.ceil(area * (1 + waste / 100))) + ' sq ft', `${num(area)} sq ft + ${waste}% waste`)}${out('Gravel base', (Math.ceil(baseYd * 2) / 2) + ' cu yd', `about ${(Math.round(baseYd * 1.4 * 10) / 10)} tons`)}${out('Bedding sand, 1 in', (Math.ceil(sandYd * 4) / 4) + ' cu yd', '')}${out('Edge restraint', num(2 * (L + W)) + ' lin ft', 'full perimeter')}${out('Polymeric sand', Math.ceil(area / 50) + ' bags', 'about 1 bag per 50 sq ft')}</div>
      <p class="tiny t3">Assumptions: 15% compaction allowance on the base, crushed stone at about 1.4 tons per cu yd, polymeric sand coverage varies with joint width. Check your supplier and the bag label.</p>`;
  } else if (tool === 'fert') {
    const nPct = f('fn', 24), target = f('ft', .75), lawn = f('fa', 8000);
    const per1k = nPct > 0 ? target / (nPct / 100) : 0, total = per1k * lawn / 1000;
    calc = `${grid(140, [inp('fn', 24, 'Nitrogen in the product (first number)', '%'), inp('ft', .75, 'Target nitrogen', 'lb N per 1,000 sq ft'), inp('fa', 8000, 'Lawn area', 'sq ft')], { gap: 10 })}
      <div class="kpis">${out('Product per 1,000 sq ft', (Math.round(per1k * 100) / 100) + ' lb', '')}${out('Product for this lawn', (Math.round(total * 10) / 10) + ' lb', `${Math.ceil(total / 50)} x 50 lb bags`)}</div>
      <p class="tiny t3">The product label rate governs. Check your state's phosphorus, setback and blackout-date rules before you apply. Licensed applicators: Rootline's crew app logs every application.</p>`;
  } else if (tool === 'snow') {
    const acres = f('sa', 1.5), rate = f('sr', 1), cost = f('sc', 95), margin = f('sm', 30), events = f('se', 18);
    const hrs = rate > 0 ? acres / rate : 0, push = hrs * cost, price = margin < 100 ? push / (1 - margin / 100) : 0;
    calc = `${grid(140, [inp('sa', 1.5, 'Paved area to plow', 'acres'), inp('sr', 1, 'Plow rate', 'acres per hour'), inp('sc', 95, 'Truck and driver cost', '$ per hour'), inp('sm', 30, 'Target margin', '%'), inp('se', 18, 'Expected pushes', 'per season')], { gap: 10 })}
      <div class="kpis">${out('Time per push', (Math.round(hrs * 100) / 100) + ' h', '')}${out('Cost per push', money(Math.round(push)), '')}${out('Price per push', money(Math.ceil(price / 5) * 5), `${margin}% margin`)}${out('Season at that price', money(Math.ceil(price / 5) * 5 * events), `${events} pushes`)}</div>
      <p class="tiny t3">Salt, sidewalks and stacking are priced separately. Use your own plow rates and your Region's push history; seasonal contracts carry the risk of a heavy winter.</p>`;
  } else {
    const L = f('ml', 46), W = f('mw', 6), D = f('md', 3), area = L * W, yd = area * D / 324;
    calc = `${grid(140, [inp('ml', 46, 'Bed length', 'ft'), inp('mw', 6, 'Bed width', 'ft'), inp('md', 3, 'Depth', 'in')], { gap: 10 })}
      <div class="kpis">${out('Bed area', num(area) + ' sq ft', '')}${out('Mulch to order', (Math.ceil(yd * 2) / 2) + ' cu yd', `${Math.round(yd * 100) / 100} cu yd exact`)}${out('Or in 2 cu ft bags', num(Math.ceil(yd * 27 / 2)) + ' bags', '')}</div>
      <p class="tiny t3">1 cubic yard covers 324 sq ft at 1 inch deep. Keep mulch 2-3 inches deep and away from trunks and stems.</p>`;
  }
  const guides = [['book', 'How to price a 400 sq ft paver patio', 'Base, edge restraint and polymeric sand, priced from production rates.', 'Guide'], ['calendar', 'The winter switch checklist', 'Cut over between November and February without missing a spring invoice.', 'Guide'], ['users', 'Onboarding a Spanish-speaking crew', 'Language settings, big-button habits and a first-week plan.', 'Guide'], ['shield', 'Chemical records your inspector can read', 'What state-format application records need to hold.', 'Guide'], ['clipboard', 'Service agreement template', 'Weekly maintenance with level billing and a renewal clause.', 'Template'], ['pen', 'Design proposal template', 'Good, better, best options with a deposit schedule.', 'Template']];
  return pageHead(c, { eyebrow: 'Resources', title: 'Free calculators, guides and templates', lede: 'Built for landscape crews and offices. Use them free, no sign-up. When you want the numbers to flow into a real estimate, that is what Rootline does.' })
  + `<div class="card" style="display:grid;gap:12px"><div class="flex between"><div class="flex">${[['mulch', 'Mulch and soil', 'layers'], ['paver', 'Paver patio materials', 'grid'], ['fert', 'Fertilizer rate per 1,000 sq ft', 'drop'], ['snow', 'Snow push pricing', 'snow']].map(([v, l, ic]) => B(l, { sm: true, ui: 'pub.calc', val: v, icon: ic, kind: tool === v ? 'primary' : '', pressed: tool === v })).join('')}</div>${h.pill('Free · no sign-up', 'ok')}</div>${calc}<div class="flex">${B('Price this job in Rootline', { kind: 'primary', go: 'www.start', icon: 'arrow-r' })}${B('Homeowner? Design your yard', { kind: 'ghost', set: 'as=homeowner&r=home.start', icon: 'sprout' })}</div></div>`
  + sec({ eyebrow: 'Guides and templates', title: 'Read, copy, use', body: grid(240, guides.map(([ic, t, d, kind]) => `<button type="button" class="card" data-act="pub-toast" data-msg="${esc(t + ' opens here (mock).')}" style="text-align:left;cursor:pointer;display:grid;gap:6px;align-content:start;font:inherit;color:inherit"><span class="flex between">${tile(ic, kind === 'Template' ? 'info' : 'ok')}${h.pill(kind, '')}</span><b class="small">${t}</b><span class="small muted">${d}</span></button>`), { gap: 10 }) })
  + conversions(c);
});

