    <div style="display:grid;gap:6px"><h1 style="font-size:clamp(1.6rem,3vw,2.2rem)">Welcome, ${esc(c.owner.split(' ')[0])}. Your Grow trial is ready.</h1><p class="muted">Trial started ${start} and runs to ${end}. ${nDone >= 4 ? `<b style="color:var(--ok-text)">Extension earned: now runs to ${ext}.</b>` : `Finish 4 of the 6 milestones below and we add 14 days.`}</p></div>
